#include <format>
#include <iostream>
#include <string>

int main() {
  std::string f = "{} {}";
  int a = 1;
  try {
    std::string s = std::vformat(f, std::make_format_args(a));
    std::cout << s << '\n';
  } catch (const std::format_error&) {
    std::cout << "format_error\n";
  }
}
